"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["26047"],{59547(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.formulario_portavel.derivacao_invalida","status":422,"titulo":"A deriva\xe7\xe3o do formul\xe1rio n\xe3o forma regras v\xe1lidas"},"descricao":{"codigo":"uniplus.formulario_portavel.derivacao_invalida","requisitos":[],"oQueAconteceu":["A avalia\xe7\xe3o de um formul\xe1rio sem cadastro confere as regras de um formul\xe1rio apresentado contra respostas simuladas, sem gravar nada nem registrar o conte\xfado enviado. Uma deriva\xe7\xe3o de fato nas regras recebidas \xe9 recusada por um destes motivos, cada um com a pr\xf3pria mensagem: uma regra sem `quando` (`field` igual a `derivacoes[d].regras[r].quando`), como \\"Uma regra da deriva\xe7\xe3o n\xe3o diz quando ativa; a regra sempre ativa tem a lista vazia.\\"; uma deriva\xe7\xe3o sem nenhuma regra (`field` igual a `derivacoes[d]`), como \\"A deriva\xe7\xe3o de \'`{fato\\\\}`\' precisa de ao menos uma regra.\\"; ou uma regra que cita o pr\xf3prio fato derivado, como \\"A deriva\xe7\xe3o de \'`{fato\\\\}`\' cita o pr\xf3prio fato \u2014 um derivado n\xe3o pode depender de si mesmo.\\"","A recusa vem na lista `errors` da resposta, uma entrada por recusa, cada uma com `field` igual ao caminho do elemento recusado nas regras enviadas, por exemplo `paginas[0].itens[2]`, ou mais fundo quando a recusa \xe9 de uma parte dele. As regras recebidas s\xe3o lidas por inteiro antes da avalia\xe7\xe3o, nesta ordem: as p\xe1ginas (com os itens e os grupos de cada uma), os termos, as deriva\xe7\xf5es, os resumos de grupo e, por fim, o conjunto, e todas as recusas de uma mesma etapa voltam juntas. A confer\xeancia do conjunto (c\xf3digo repetido, refer\xeancia a algo que o formul\xe1rio n\xe3o tem) s\xf3 vem depois que nenhum elemento foi recusado, e \xe9 a \xfanica recusa sem `field`. Havendo defeito de estrutura do documento (elemento nulo numa lista ou grupo sem `ocorrencias`), s\xf3 as recusas de estrutura voltam, cada uma no caminho do elemento, e nada mais \xe9 lido. Numa mesma deriva\xe7\xe3o, todas as regras s\xe3o lidas e o c\xf3digo do fato, que vem depois delas, \xe9 conferido no campo `derivacoes[d].fatoCodigo` (essa recusa tem o c\xf3digo de [estrutura inv\xe1lida](/erros/uniplus.formulario_portavel.estrutura_invalida)); as regras da deriva\xe7\xe3o s\xf3 s\xe3o avaliadas quando nada dela foi recusado. Todas as recusas da condi\xe7\xe3o de `quando` voltam, cada uma com o caminho completo, como `derivacoes[0].regras[0].quando[0][1].operador`, e a contribui\xe7\xe3o da regra n\xe3o \xe9 conferida. A regra de deriva\xe7\xe3o categ\xf3rica sem o c\xf3digo que contribui \xe9 recusada com outro c\xf3digo.","As propriedades de texto que o corpo n\xe3o pode omitir, como o c\xf3digo, a obrigatoriedade e a opera\xe7\xe3o, ausentes ou nulas, s\xe3o recusadas antes, com 400 e sem c\xf3digo deste cat\xe1logo, pela leitura do corpo."],"comoResolver":["Informe `quando` em toda regra, usando a lista vazia para a regra sempre ativa; mantenha ao menos uma regra em cada deriva\xe7\xe3o; e tire de cada regra a cita\xe7\xe3o ao pr\xf3prio fato derivado. Depois, repita a avalia\xe7\xe3o."],"ondeAparece":["Avalia\xe7\xe3o de formul\xe1rio sem cadastro"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Formulario portavel"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);